#!/usr/bin/env python3
"""Render the ledger owner's explicit document-by-document semantic decisions.

Only paths registered below are reviewed.  No keyword rule certifies an
unlisted document, and old textual variants require explicit registration.
"""
import gzip
import hashlib
import json
import re
import itertools
from pathlib import Path
from canonical import BASELINE, native, power, incoming, outgoing, reference

HERE=Path(__file__).resolve().parent
SOURCES=json.loads(gzip.decompress((HERE/'inventory/public_sources.json.gz').read_bytes()))
DOCUMENTS=[]
CLAIMS=[]


def document(path, *, claim_ids=(), group=None, charges=None, result=None,
             order='classical', source=None, target=None, field='Q',
             normalization='Dimensions and ranks are invariant under nonzero basis rescaling; literal representatives retain the pinned source normalization.',
             scope='', limits=(), identifier=None, all_variants=False,
             classification='in_scope', excluded=None, state='historical'):
    candidates={}
    for key,value in SOURCES.items():
        if value.get('path')==path or key==path:
            candidates.setdefault(value['sha256'],[]).append((key,value))
    if not candidates:
        raise ValueError('Not in the fixed public queue: '+path)
    if not all_variants:
        selected=max(candidates,key=lambda sha:len(candidates[sha][0][1]['text']))
        candidates={selected:candidates[selected]}
    ids=list(claim_ids)
    if result is not None:
        if not group or not charges:
            raise ValueError('An attributed result needs its actual group and charge domain: '+path)
        identifier=identifier or 'public-'+re.sub('[^a-z0-9]+','-',path.lower()).strip('-')
        ids.append(identifier)
        certificates=[];versions=[]
        for sha,items in candidates.items():
            key,body=next(((k,v) for k,v in items if k.startswith(BASELINE+':')),items[0])
            if body['kind']=='git-document':
                certificates.append(reference(body['path'],body['commit']))
            else:
                certificates.append({'kind':'workspace','path':'research-roadmap/claim-ledger/issue-1-snapshot.json'})
            versions.append({'source':key,'sha256':sha,
                             'literal_advertised_statement':body['text'],
                             'attribution':'Exact public text; its individual assertions retain all stated hypotheses and dates.'})
        CLAIMS.append({'id':identifier,'theory':'undeformed four-dimensional N=4 SYM',
                       'group':group,'title':result['title'],
                       'proposition':{'key':'public-attribution/'+identifier,'value':result['outcomes']},
                       'charges':charges,
                       'source':source or {'kind':'not_applicable','reason':'Dimension, identity, method or existence result rather than a specified map.'},
                       'target':target or {'kind':'not_applicable','reason':'Dimension, identity, method or existence result rather than a specified map.'},
                       'order':order,'direction':'Exactly the directions and parameter ranges in the detailed native statement.',
                       'field':field,'normalization':normalization,
                       'scope':{'description':scope or result['title'],
                                'completeness':'The exact complete/selected/conditional limits are preserved in the full attributed statement and in limitations.',
                                'physical_identification':'No formal result is upgraded to an unconditional physical statement.'},
                       'certificate':certificates,'supersession_state':state,
                       'proof_status':'attributed_public_result','supersedes':[],
                       'limitations':list(limits)+['This semantic import does not assert a new independent replay or a new scientific result.'],
                       'unresolved_metadata':[],'advertisements':[p['source'] for p in versions],
                       'deduplication':{'role':'supporting_evidence_packet' if claim_ids else 'additional_attributed_result_packet',
                                        'canonical_semantic_links':list(claim_ids),
                                        'scientific_count_increment':None,
                                        'rule':'An evidence packet is not another discovery. Repeated claims and historical versions retain their canonical links and literal evidence contexts.'},
                       'counting_unit':'One attributed result packet; its intermediate rank checks are not additional target or generator discoveries.',
                       'statement_versions':versions})
    for sha,items in candidates.items():
        key,body=items[0]
        headings=[re.sub(r'^#+\s*','',line).strip() for line in body['text'].splitlines() if re.match(r'^#{1,6}\s',line)]
        assertions=[]
        if classification in ['in_scope','mixed']:
            if not ids:
                raise ValueError('In-scope reviewed document has no mapped semantic result: '+path)
            assertions=[{'location':'Complete document; headings: '+'; '.join(headings),
                         'claim_ids':ids,
                         'description':scope or (result['title'] if result else 'The mapped result, its exact support identities, scope and limits; all numeric tables retain their literal source fields.')}]
        DOCUMENTS.append({'sha256':sha,'classification':classification,'review_complete':True,
                          'claim_ids':ids,'covered_assertions':assertions,
                          'scope_exclusions':excluded or [{'location':'Replay commands, environment prerequisites and bibliographic navigation',
                              'reason':'These specify provenance and how to verify the mapped result; they are not additional undeformed-N4 scientific claims.'}],
                          'metadata_gaps':[],
                          'notes':'All mathematical assertions are attributed at their stated scope. Exact source bytes and every immutable occurrence remain archived.'})


